<link rel="stylesheet" href="<?=asset('css/writer-login.css')?>">
<main class="auth-verify write-main" aria-labelledby="verify-title">
<a class="auth-back" href="<?=url('/write/login')?>">← Back to sign-in</a>
<section class="auth-card"><span class="login-eyebrow">Step 2 · Secure access</span><h1 id="verify-title">Verify it’s you.</h1>
<?php if($error!==''):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?>
<?php if($challenge):$method=$challenge['method'];$methods=wa_methods($challenge);?>
<p class="auth-subtitle"><?php if($method==='email'):?>Enter the code for <strong><?=e(wa_mask($challenge['email']))?></strong>.<?php elseif($method==='totp'):?>Open your authenticator app and enter the current six-digit code.<?php elseif($method==='sms'):?>Enter the code from the text sent to your verified phone.<?php else:?>Enter one of the recovery codes you saved during setup.<?php endif;?></p>
<?php if(in_array($method,['email','sms'],true)):?><p class="auth-delivery" role="status"><?=($challenge['delivery']??'')==='accepted'?'Your code request was accepted. Check your inbox or messages.':'The code has not been sent. Request a code below or choose another enrolled method.'?></p><?php endif;?>
<form method="post" action="<?=url('/write/verify')?>" class="auth-code-form"><?=csrf_field()?><input type="hidden" name="action" value="verify"><label for="verification-code"><?=$method==='recovery'?'Recovery code':'Verification code'?></label><input id="verification-code" class="auth-code" name="code" type="text" inputmode="<?=$method==='recovery'?'text':'numeric'?>" autocomplete="one-time-code" autocapitalize="none" spellcheck="false" maxlength="<?=$method==='recovery'?40:10?>" required autofocus aria-describedby="code-help"><p id="code-help" class="login-hint"><?=$method==='totp'?'Use the current code; your authenticator refreshes it every 30 seconds.':($method==='recovery'?'Each recovery code can be used once.':'This sign-in request expires after 10 minutes. Each code can be used once.')?></p><button class="wbtn primary">Verify & continue <span aria-hidden="true">→</span></button></form>
<div class="auth-alternatives"><h2>Another way to verify</h2><?php foreach($methods as$key=>$label):?><form method="post" action="<?=url('/write/verify')?>"><?=csrf_field()?><input type="hidden" name="action" value="method"><input type="hidden" name="method" value="<?=e($key)?>"><button class="wbtn" <?=$key===$method&&!in_array($key,['email','sms'],true)?'disabled':''?>><?=e($key===$method?(in_array($key,['email','sms'],true)?'Request a new '.($key==='email'?'email':'text').' code':$label.' · selected'):$label)?></button></form><?php endforeach;?></div>
<form method="post" action="<?=url('/write/verify')?>"><?=csrf_field()?><button class="auth-text-button" name="action" value="cancel">Cancel this sign-in</button></form>
<?php else:?><p>Start a fresh sign-in to receive a new verification request.</p><a class="wbtn primary" href="<?=url('/write/login')?>">Return to sign-in</a><?php endif;?>
</section><p class="auth-footer">Waithaka Ndegwa · Your private workspace</p></main>
